import React, { useEffect, useRef, useState } from 'react';
import axios from 'axios';

const Chart = ({ symbol = 'BTCUSD', timeframe = '1H', patterns = [] }) => {
  const chartRef = useRef(null);
  const widgetRef = useRef(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    // Check if TradingView library is available
    if (!window.TradingView || !window.TradingView.widget) {
      console.warn('TradingView library not found, using fallback chart');
      setError('TradingView library not loaded - using fallback chart');
      setIsLoading(false);
      return;
    }

    // Cleanup previous widget
    if (widgetRef.current) {
      try {
        widgetRef.current.remove();
      } catch (e) {
        console.warn('Error removing previous widget:', e);
      }
    }

    setIsLoading(true);
    setError(null);

    try {
      // Create TradingView widget
      const widget = new window.TradingView.widget({
        autosize: true,
        symbol: symbol,
        interval: timeframe,
        container: chartRef.current,
        library_path: '/charting_library/',
        locale: 'en',
        disabled_features: [
          'use_localstorage_for_settings',
          'volume_force_overlay'
        ],
        enabled_features: [
          'study_templates'
        ],
        fullscreen: false,
        autosize: true,
        theme: 'dark',
        loading_screen: {
          backgroundColor: '#1a1a1a',
          foregroundColor: '#00d084'
        },
        overrides: {
          'paneProperties.background': '#1a1a1a',
          'paneProperties.vertGridProperties.color': '#333333',
          'paneProperties.horzGridProperties.color': '#333333',
          'symbolWatermarkProperties.transparency': 90,
          'scalesProperties.textColor': '#a0a0a0',
          'mainSeriesProperties.candleStyle.upColor': '#00d084',
          'mainSeriesProperties.candleStyle.downColor': '#ff4747',
          'mainSeriesProperties.candleStyle.drawWick': true,
          'mainSeriesProperties.candleStyle.drawBorder': true,
          'mainSeriesProperties.candleStyle.borderColor': '#378658',
          'mainSeriesProperties.candleStyle.borderUpColor': '#00d084',
          'mainSeriesProperties.candleStyle.borderDownColor': '#ff4747',
          'mainSeriesProperties.candleStyle.wickUpColor': '#00d084',
          'mainSeriesProperties.candleStyle.wickDownColor': '#ff4747'
        }
      });

      widget.onChartReady(() => {
        setIsLoading(false);
        
        // Add pattern overlays
        if (patterns && patterns.length > 0) {
          drawPatterns(widget, patterns);
        }
      });

      widgetRef.current = widget;

    } catch (err) {
      console.error('Error creating TradingView widget:', err);
      setError('Failed to load chart');
      setIsLoading(false);
    }

    return () => {
      if (widgetRef.current) {
        try {
          widgetRef.current.remove();
        } catch (err) {
          console.error('Error removing widget:', err);
        }
      }
    };
  }, [symbol, timeframe]);

  useEffect(() => {
    // Update patterns when they change
    if (widgetRef.current && patterns) {
      drawPatterns(widgetRef.current, patterns);
    }
  }, [patterns]);

  const drawPatterns = (widget, patternList) => {
    try {
      widget.activeChart().executeActionById('drawingToolbarAction');
      
      patternList.forEach((pattern, index) => {
        if (pattern.status === 'completed' && pattern.points) {
          drawHarmonicPattern(widget, pattern, index);
        }
      });
    } catch (err) {
      console.error('Error drawing patterns:', err);
    }
  };

  const drawHarmonicPattern = (widget, pattern, index) => {
    try {
      const chart = widget.activeChart();
      const { points, type } = pattern;
      
      // Get pattern color
      const patternColors = {
        'Gartley': '#00d084',
        'Bat': '#2196f3',
        'Butterfly': '#ff9800',
        'Crab': '#ff4747',
        'Cypher': '#9c27b0',
        'Shark': '#607d8b',
        'ABCD': '#ffc107'
      };
      
      const color = patternColors[type] || '#ffffff';
      
      // Draw pattern lines
      if (points.X && points.A && points.B && points.C && points.D) {
        // XA line
        chart.createShape(
          { time: points.X.time, price: points.X.price },
          {
            shape: 'trend_line',
            overrides: {
              linecolor: color,
              linewidth: 2,
              linestyle: 0
            }
          },
          { time: points.A.time, price: points.A.price }
        );
        
        // AB line
        chart.createShape(
          { time: points.A.time, price: points.A.price },
          {
            shape: 'trend_line',
            overrides: {
              linecolor: color,
              linewidth: 2,
              linestyle: 0
            }
          },
          { time: points.B.time, price: points.B.price }
        );
        
        // BC line
        chart.createShape(
          { time: points.B.time, price: points.B.price },
          {
            shape: 'trend_line',
            overrides: {
              linecolor: color,
              linewidth: 2,
              linestyle: 0
            }
          },
          { time: points.C.time, price: points.C.price }
        );
        
        // CD line
        chart.createShape(
          { time: points.C.time, price: points.C.price },
          {
            shape: 'trend_line',
            overrides: {
              linecolor: color,
              linewidth: 2,
              linestyle: 0
            }
          },
          { time: points.D.time, price: points.D.price }
        );
        
        // XB line (internal)
        chart.createShape(
          { time: points.X.time, price: points.X.price },
          {
            shape: 'trend_line',
            overrides: {
              linecolor: color,
              linewidth: 1,
              linestyle: 2,
              transparency: 50
            }
          },
          { time: points.B.time, price: points.B.price }
        );
        
        // AC line (internal)
        chart.createShape(
          { time: points.A.time, price: points.A.price },
          {
            shape: 'trend_line',
            overrides: {
              linecolor: color,
              linewidth: 1,
              linestyle: 2,
              transparency: 50
            }
          },
          { time: points.C.time, price: points.C.price }
        );
        
        // Add pattern labels
        chart.createShape(
          { time: points.X.time, price: points.X.price },
          {
            shape: 'text',
            text: 'X',
            overrides: {
              color: color,
              fontsize: 12,
              bold: true
            }
          }
        );
        
        chart.createShape(
          { time: points.A.time, price: points.A.price },
          {
            shape: 'text',
            text: 'A',
            overrides: {
              color: color,
              fontsize: 12,
              bold: true
            }
          }
        );
        
        chart.createShape(
          { time: points.B.time, price: points.B.price },
          {
            shape: 'text',
            text: 'B',
            overrides: {
              color: color,
              fontsize: 12,
              bold: true
            }
          }
        );
        
        chart.createShape(
          { time: points.C.time, price: points.C.price },
          {
            shape: 'text',
            text: 'C',
            overrides: {
              color: color,
              fontsize: 12,
              bold: true
            }
          }
        );
        
        chart.createShape(
          { time: points.D.time, price: points.D.price },
          {
            shape: 'text',
            text: `D (${type})`,
            overrides: {
              color: color,
              fontsize: 12,
              bold: true
            }
          }
        );
      }
    } catch (err) {
      console.error('Error drawing harmonic pattern:', err);
    }
  };

  if (error) {
    return (
      <div className="flex items-center justify-center h-full bg-bg-secondary rounded-lg border border-border-color">
        <div className="text-center">
          <div className="text-accent-red text-lg mb-2">⚠️ Chart Error</div>
          <div className="text-text-secondary">{error}</div>
          <button 
            onClick={() => window.location.reload()}
            className="mt-4 bg-accent-blue hover:bg-blue-600 text-white px-4 py-2 rounded text-sm transition-colors"
          >
            Reload
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="relative h-full bg-bg-secondary rounded-lg border border-border-color overflow-hidden">
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-bg-secondary z-10">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-accent-green mx-auto mb-4"></div>
            <div className="text-text-secondary">Loading chart...</div>
          </div>
        </div>
      )}
      
      <div 
        ref={chartRef}
        className="w-full h-full"
        style={{ minHeight: '400px' }}
      />
      
      {/* Pattern Info Overlay */}
      {patterns && patterns.length > 0 && (
        <div className="absolute top-4 left-4 bg-bg-tertiary border border-border-color rounded p-3 z-20">
          <div className="text-sm font-semibold mb-2">Active Patterns</div>
          {patterns.slice(0, 3).map((pattern, index) => (
            <div key={index} className="text-xs text-text-secondary mb-1">
              <span className={`inline-block w-2 h-2 rounded-full mr-2`} 
                    style={{ backgroundColor: getPatternColor(pattern.type) }}>
              </span>
              {pattern.type} - {pattern.status}
            </div>
          ))}
          {patterns.length > 3 && (
            <div className="text-xs text-text-secondary">
              +{patterns.length - 3} more patterns
            </div>
          )}
        </div>
      )}
    </div>
  );
};

const getPatternColor = (type) => {
  const colors = {
    'Gartley': '#00d084',
    'Bat': '#2196f3',
    'Butterfly': '#ff9800',
    'Crab': '#ff4747',
    'Cypher': '#9c27b0',
    'Shark': '#607d8b',
    'ABCD': '#ffc107'
  };
  return colors[type] || '#ffffff';
};

export default Chart;
